defmodule Prism.Generator.HeaderTest do
  use ExUnit.Case, async: true

  alias Prism.Generator.Header

  @moduletag :tmp_dir

  test "the line names the design's file, in the comment syntax of the file" do
    assert Header.line("tailwind.preset.js", "theme/lib/a.ex") ==
             "// Generated by prism (mix prism.gen). Do not edit: change theme/lib/a.ex and regenerate."

    assert Header.line("src/Button.tsx", "theme/lib/a.ex") ==
             "// Generated by prism (mix prism.gen). Do not edit: change theme/lib/a.ex and regenerate."

    assert Header.line("src/index.ts", "theme/lib/a.ex") =~ ~r"\A// Generated by prism"

    assert Header.line("Sources/Acme/Tokens.swift", "theme/lib/a.ex") ==
             "// Generated by prism (mix prism.gen). Do not edit: change theme/lib/a.ex and regenerate."

    assert Header.line("css/base.css", "theme/lib/a.ex") ==
             "/* Generated by prism (mix prism.gen). Do not edit: change theme/lib/a.ex and regenerate. */"
  end

  test "an SVG's header is an XML comment, a JSON file's the root's $description" do
    assert Header.line("overview.svg", "lib/a.ex") ==
             "<!-- Generated by prism (mix prism.gen). Do not edit: change lib/a.ex and regenerate. -->"

    assert Header.put("overview.svg", "lib/a.ex", "<svg/>\n") ==
             Header.line("overview.svg", "lib/a.ex") <> "\n<svg/>\n"

    assert Header.put("tokens.json", "lib/a.ex", ~s({\n  "color": {}\n}\n)) ==
             ~s|{\n  "$description": "Generated by prism (mix prism.gen). Do not edit: change lib/a.ex and regenerate.",\n  "color": {}\n}\n|

    # An empty object's only member is the header.
    assert Header.put("tokens.json", "lib/a.ex", "{\n}\n") ==
             ~s|{\n  "$description": "Generated by prism (mix prism.gen). Do not edit: change lib/a.ex and regenerate."\n}\n|

    assert_raise ArgumentError, ~r/must be an object/, fn ->
      Header.put("a.json", "a.ex", "[]")
    end

    # `--` ends an XML comment.
    assert_raise ArgumentError, ~r/can't be written in a comment/, fn ->
      Header.line("overview.svg", "lib/a--b.ex")
    end
  end

  test "text that can't be a comment, or a file type without a comment syntax, fails" do
    assert_raise ArgumentError, ~r/can't be written in a comment/, fn ->
      Header.line("css/base.css", "lib/*/a.ex")
    end

    assert_raise ArgumentError, ~r/no comment syntax for .txt files/, fn ->
      Header.line("notes.txt", "lib/a.ex")
    end
  end

  test "exact? recognises only the whole line, in a file type with a header", %{tmp_dir: dir} do
    write = fn name, body ->
      path = Path.join(dir, name)
      File.write!(path, body)
      path
    end

    assert Header.exact?(write.("a.css", Header.put("a.css", "lib/a.ex", "a {}\n")))
    assert Header.exact?(write.("a.tsx", Header.put("a.tsx", "lib/b.ex", "x\n")))
    assert Header.exact?(write.("a.swift", Header.put("a.swift", "lib/b.ex", "import SwiftUI\n")))
    assert Header.exact?(write.("a.json", Header.put("a.json", "lib/a.ex", "{\n  \"a\": 1\n}\n")))
    assert Header.exact?(write.("b.json", Header.put("b.json", "lib/a.ex", "{\n}\n")))

    line = Header.line("a.css", "lib/a.ex")
    refute Header.exact?(write.("b.css", "/* Generated by prism, then edited */\n"))
    refute Header.exact?(write.("c.css", String.replace(line, " */", " edited */") <> "\n"))
    refute Header.exact?(write.("d.css", "a {}\n" <> line <> "\n"))
    refute Header.exact?(write.("a.md", "Generated by prism (mix prism.gen).\n"))
    refute Header.exact?(write.("e.css", "/* hand-written */\n"))
    refute Header.exact?(write.("d.json", ~s({\n  "$description": "Mine",\n  "color": {}\n}\n)))

    refute Header.exact?(
             write.("c.json", ~s({\n  "$description": "Generated by prism, mine"\n}\n))
           )
  end
end
